import {stages,taskStates,roleNames,isStaff} from './staff.js';
export function createStaffUI(c){
 const {esc,icon,money,heading,empty,openModal,toast}=c,s=()=>c.state();let userFilter='';
 const names={'staff-home':'Панель управления','staff-projects':'Контроль проектов','staff-tasks':'Задачи и сроки','staff-requests':'Заявки проектов','admin-users':'Пользователи','admin-moderation':'Модерация каталога','staff-audit':'Журнал сотрудников'};
 const auditTypes={account:'Статус аккаунта',role:'Роль пользователя',assignment:'Назначение менеджера',profile:'Модерация профиля',review:'Модерация отзыва',stage:'Этап проекта',note:'Внутренняя заметка',task:'Задача'};
 const admin=()=>s().user.role==='admin';
 const targetName=pid=>s().projects.find(p=>p.id===pid)?.name||s().accounts.find(u=>u.id===pid)?.name||s().profiles.find(p=>p.id===pid)?.name||s().reviews.find(r=>r.id===pid)?.author||'—';
 const projectName=pid=>s().projects.find(p=>p.id===pid)?.name||pid;
 const staffStats=()=>{const data=s();return `<div class="stats">${[['Проекты под контролем',data.projects.length,'folder'],['Ожидают решения клиента',data.estimates.filter(e=>e.status==='pending').length,'clock'],['Открытые задачи',data.tasks.filter(t=>t.status!=='done').length,'list'],[admin()?'Пользователи платформы':'Мои записи в журнале',admin()?data.accounts.length:data.staffAudit.length,'shield']].map(([label,value,i],j)=>`<div class="stat ${j===0?'highlight':''}"><div class="stat-top">${label}<span class="stat-icon">${icon(i,16)}</span></div><div class="stat-value">${value}</div><small>${admin()?'По всей платформе':'Только назначенные проекты'}</small></div>`).join('')}</div>`;};
 const pending=()=>{const rows=s().estimates.filter(e=>e.status==='pending');return `<section class="panel"><div class="panel-head"><h2>Ожидают решения клиента</h2></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Смета / проект</th><th>Сумма</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${esc(projectName(e.projectId))}</small></td><td>${money(c.total(e.lines))}</td><td><button class="link-btn" data-go="estimate" data-id="${e.id}">Посмотреть</button></td></tr>`).join('')}</tbody></table></div>`:empty('Нет смет, ожидающих решения.')}</section>`;};
 function home(){return `${heading(admin()?'Администрирование платформы':'Рабочий день менеджера',admin()?'Пользователи, назначения и качество каталога.':'Контроль этапов, задач и согласований назначенных проектов.','','Команда RenoLock')}${staffStats()}<div class="notice">Решения по расходам принимает заказчик. Сотрудники не могут утверждать сметы или менять согласованные суммы.</div><div class="staff-shortcuts">${[['staff-projects','folder','Контроль проектов'],['staff-tasks','list','Задачи и сроки'],...(admin()?[['admin-users','building','Пользователи'],['admin-moderation','shield','Модерация каталога']]:[['staff-requests','file','Заявки проектов']])].map(([page,i,name])=>`<button class="panel staff-shortcut" data-go="${page}">${icon(i,22)}<strong>${name}</strong>${icon('arrow',16)}</button>`).join('')}</div>${pending()}${auditPanel(5)}`;}
 function projects(){return `${heading('Контроль проектов','Операционные этапы не меняют бюджет и статус финансовых согласований.')}<div class="staff-project-list">${s().projects.map(p=>{const b=c.budget(p,s().estimates);return `<section class="panel"><div class="panel-head"><div><h2>${esc(p.name)}</h2><small>${esc(p.address)}</small></div><span class="badge ${p.completedAt?'approved':'changes'}">${p.completedAt?'Проект завершён':stages[p.stage||'planning']}</span></div><div class="panel-body"><div class="staff-project-meta"><div><small>Подрядчик</small><strong>${esc(s().people.find(u=>u.id===p.contractorId)?.name||'—')}</strong></div><div><small>Заказчик</small><strong>${esc(s().people.find(u=>u.id===p.clientId)?.name||'—')}</strong></div><div><small>Менеджер</small><strong>${esc(s().people.find(u=>u.id===p.managerId)?.name||'Не назначен')}</strong></div><div><small>Утверждённый бюджет</small><strong>${money(b.current)}</strong></div></div><div class="actions"><button class="btn" data-go="project" data-id="${p.id}">Открыть проект</button><button class="btn" data-go="report" data-id="${p.id}">Отчёт</button>${!p.completedAt?`<button class="btn primary" data-act="staff-stage" data-id="${p.id}">Обновить этап</button><button class="btn" data-act="staff-task-new" data-id="${p.id}">Добавить задачу</button>`:''}<button class="btn" data-act="staff-note" data-id="${p.id}">Добавить заметку</button>${admin()?`<button class="btn" data-act="staff-assign" data-id="${p.id}">Назначить менеджера</button>`:''}</div>${c.lifecyclePanel("project",p,true)}<details class="request-history"><summary>Внутренние заметки</summary>${s().projectNotes.filter(n=>n.projectId===p.id).map(n=>`<p><strong>${esc(n.actor)}</strong> · ${c.date(n.at)}<br>${esc(n.text)}</p>`).join('')||'<p>Заметок пока нет.</p>'}</details></div></section>`;}).join('')||empty('Проекты ещё не назначены. Обратитесь к администратору.')}</div>`;}
 function tasks(){return `${heading('Задачи и сроки','Внутренние задачи команды платформы.',s().projects.some(p=>!p.completedAt)?'<button class="btn primary" data-act="staff-task-new">Добавить задачу</button>':'')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Задача</th><th>Срок</th><th>Статус</th><th></th></tr></thead><tbody>${s().tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(projectName(t.projectId))}</small></td><td>${esc(t.dueDate)}</td><td><span class="badge ${t.status==='done'?'approved':t.status==='doing'?'changes':'pending'}">${taskStates[t.status]}</span></td><td><button class="link-btn" data-act="staff-task-status" data-id="${t.id}">Изменить статус</button></td></tr>`).join('')||'<tr><td colspan="4">Задач пока нет.</td></tr>'}</tbody></table></div></section>`;}
 function requests(){return `${heading('Заявки проектов','Просмотр заявок, связанных с доступными проектами.')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Заявка</th><th>Заказчик / исполнитель</th><th>Статус</th><th></th></tr></thead><tbody>${s().requests.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${r.area} м² · ${esc(r.repairClass)}</small></td><td>${esc(r.clientName)}<small>${esc(r.contractorName)}</small></td><td>${({requested:'Ожидает предложения',quoted:'Предложение получено',accepted:'Проект создан',declined:'Отклонено'})[r.status]}</td><td>${r.projectId?`<button class="link-btn" data-go="project" data-id="${r.projectId}">Открыть проект</button>`:'<span class="muted">Проект ещё не создан</span>'}</td></tr>`).join('')||'<tr><td colspan="4">Заявок пока нет.</td></tr>'}</tbody></table></div></section>`;}
 function users(){return `${heading('Пользователи','Управление доступом без удаления аккаунтов и истории.')}<div class="notice">Менеджера можно назначить из свободного зарегистрированного аккаунта без проектов и профиля исполнителя. Роли сотрудников недоступны при публичной регистрации.</div><form id="staff-user-filter" class="filter-bar"><input name="q" class="search" value="${esc(userFilter)}" placeholder="Поиск по имени или email" aria-label="Поиск пользователей"><button class="btn">Найти</button></form><section class="panel"><div class="table-wrap"><table><thead><tr><th>Пользователь</th><th>Роль</th><th>Доступ</th><th>Действия</th></tr></thead><tbody>${s().accounts.filter(u=>(u.name+' '+u.email).toLowerCase().includes(userFilter.toLowerCase())).map(u=>{const linked=s().projects.some(p=>[p.clientId,p.contractorId,p.managerId].includes(u.id))||s().requests.some(r=>[r.clientId,r.contractorId].includes(u.id))||s().profiles.some(p=>p.ownerId===u.id);return `<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${roleNames[u.role]}</td><td><span class="badge ${u.blocked?'rejected':'approved'}">${u.blocked?'Заблокирован':'Активен'}</span></td><td><div class="actions">${u.role!=='admin'?`<button class="btn small ${u.blocked?'':'danger'}" data-act="staff-account" data-id="${u.id}">${u.blocked?'Разблокировать':'Заблокировать'}</button>`:'<small>Защищённая роль</small>'}${!linked&&u.role!=='admin'?`<button class="btn small" data-act="staff-role" data-id="${u.id}">${u.role==='manager'?'Вернуть роль клиента':'Назначить менеджером'}</button>`:''}</div></td></tr>`;}).join('')}</tbody></table></div></section>`;}
 function moderation(){return `${heading('Модерация каталога','Скрытие и восстановление публикаций с обязательной причиной.')}<section class="panel"><div class="panel-head"><h2>Профили исполнителей</h2></div><div class="table-wrap"><table><thead><tr><th>Профиль</th><th>Публикация</th><th>Причина модерации</th><th></th></tr></thead><tbody>${s().profiles.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.city)} · ${esc(p.specialty)}</small></td><td><span class="badge ${p.moderationHidden?'rejected':'approved'}">${p.moderationHidden?'Скрыт модератором':p.active?'В каталоге':'Скрыт владельцем'}</span></td><td>${esc(p.moderationReason||'—')}</td><td><button class="btn small" data-act="staff-profile-moderate" data-id="${p.id}">${p.moderationHidden?'Восстановить':'Скрыть'}</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Отзывы</h2></div><div class="panel-body">${s().reviews.map(r=>`<article class="review"><div class="actions"><strong>${esc(r.author)}</strong><span class="rating">${r.rating} ★</span><span class="badge ${r.hidden?'rejected':'approved'}">${r.hidden?'Скрыт модератором':'Опубликован'}</span><button class="btn small" data-act="staff-review-moderate" data-id="${r.id}">${r.hidden?'Восстановить':'Скрыть'}</button></div><small>${esc(s().profiles.find(p=>p.id===r.profileId)?.name||'')}</small><p>${esc(r.text)}</p>${r.moderationReason?`<small>Причина: ${esc(r.moderationReason)}</small>`:''}</article>`).join('')||empty('Отзывов пока нет.')}</div></section>`;}
 function auditPanel(limit){const rows=[...s().staffAudit].reverse().slice(0,limit);return `<section class="panel"><div class="panel-head"><h2>Журнал сотрудников</h2></div><div class="table-wrap"><table><thead><tr><th>Когда / кто</th><th>Действие</th><th>Комментарий</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${c.date(a.at)}<small>${esc(a.actor)}</small></td><td><strong>${auditTypes[a.type]||esc(a.type)}</strong><small>${esc(targetName(a.targetId))}</small></td><td>${esc(a.comment)}</td></tr>`).join('')||'<tr><td colspan="3">Действий пока нет.</td></tr>'}</tbody></table></div></section>`;}
 function readEstimate(route){const e=s().estimates.find(e=>e.id===route.id);if(!e)return empty('Смета недоступна.');return `${heading(esc(e.title),esc(projectName(e.projectId)),`<button class="btn" data-go="project" data-id="${e.projectId}">Открыть проект</button>`)}<div class="notice">Режим просмотра сотрудника. Решения по смете принимает только заказчик.</div>${c.executionPanel(e,true)}<section class="panel"><div class="panel-head"><h2>Смета дополнительных работ</h2>${c.badge(e.status)}</div>${c.linesTable(e.lines)}</section><section class="panel"><div class="panel-head"><h2>История этой сметы</h2></div><div class="panel-body">${c.logList(s().logs.filter(l=>l.estimateId===e.id).slice().reverse())}</div></section>`;}
 const modalForm=(title,type,fields,recordId,extra='')=>openModal(title,`<form id="staff-action-form" data-type="${type}" data-id="${recordId||''}" ${extra}>${fields}<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-act="modal-close">Отмена</button><button class="btn primary">Сохранить</button></div></form>`);
 const options=(items,current)=>Object.entries(items).map(([key,label])=>`<option value="${key}" ${key===current?'selected':''}>${label}</option>`).join('');
 async function click(act,b){if(!s()||!isStaff(s().user))return false;switch(act){
 case 'staff-stage':{const p=s().projects.find(p=>p.id===b.dataset.id);modalForm('Обновить этап','manager.project.stage',`<label class="field">Этап проекта<select name="stage">${options(stages,p.stage||'planning')}</select></label>`,p.id);return true;}
 case 'staff-note':modalForm('Внутренняя заметка','manager.note.add','<div class="notice">Заметка видна только сотрудникам, имеющим доступ к проекту.</div><label class="field">Текст заметки<textarea name="text" required maxlength="2000"></textarea></label>',b.dataset.id);return true;
 case 'staff-task-new':modalForm('Добавить задачу','manager.task.create',`<label class="field">Проект<select name="projectId">${s().projects.filter(p=>!p.completedAt).map(p=>`<option value="${p.id}" ${p.id===b.dataset.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Название задачи<input name="title" required maxlength="200"></label><label class="field">Срок выполнения<input name="dueDate" type="date" required></label>`);return true;
 case 'staff-task-status':{const task=s().tasks.find(t=>t.id===b.dataset.id);modalForm('Изменить статус','manager.task.status',`<label class="field">Статус задачи<select name="status">${options(taskStates,task.status)}</select></label>`,task.id);return true;}
 case 'staff-assign':{const p=s().projects.find(p=>p.id===b.dataset.id);modalForm('Назначить менеджера','admin.project.assign',`<label class="field">Менеджер<select name="managerId"><option value="">Не назначен</option>${s().managers.map(m=>`<option value="${m.id}" ${p.managerId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`,p.id);return true;}
 case 'staff-account':case 'staff-role':{const u=s().accounts.find(u=>u.id===b.dataset.id),role=act==='staff-role';modalForm(role?'Изменение роли':'Изменение доступа',role?'admin.user.role':'admin.user.status',`<p>${esc(u.name)} · ${esc(u.email)}</p><div class="notice">${role?'Роль изменится после сохранения. Текущие сессии будут завершены.':u.blocked?'Доступ пользователя будет восстановлен.':'Пользователь потеряет доступ. Его проекты и история сохранятся.'}</div><label class="field">Причина<textarea name="comment" required maxlength="1000"></textarea></label>`,u.id,role?`data-role="${u.role==='manager'?'client':'manager'}"`:`data-blocked="${!u.blocked}"`);return true;}
 case 'staff-profile-moderate':case 'staff-review-moderate':{const profile=act==='staff-profile-moderate',r=(profile?s().profiles:s().reviews).find(r=>r.id===b.dataset.id),hidden=profile?r.moderationHidden:r.hidden;modalForm(hidden?'Восстановить публикацию':'Скрыть публикацию',profile?'admin.profile.moderate':'admin.review.moderate','<label class="field">Причина модерации<textarea name="reason" required maxlength="1000"></textarea></label>',r.id,`data-hidden="${!hidden}"`);return true;}
 }return false;}
 document.addEventListener('submit',async event=>{const form=event.target;if(!['staff-action-form','staff-user-filter'].includes(form.id))return;event.preventDefault();if(!s()||!isStaff(s().user))return;const button=form.querySelector('button.primary,button');if(button.disabled)return;button.disabled=true;try{const d=Object.fromEntries(new FormData(form));if(form.id==='staff-user-filter'){userFilter=d.q;c.render();return;}const data={...d,id:form.dataset.id};if(form.dataset.type==='manager.note.add'||form.dataset.type==='admin.project.assign')data.projectId=form.dataset.id;if(form.dataset.blocked)data.blocked=form.dataset.blocked==='true';if(form.dataset.hidden)data.hidden=form.dataset.hidden==='true';if(form.dataset.role)data.role=form.dataset.role;await c.action(form.dataset.type,data);await c.refresh();c.closeModal();c.render();toast('Сохранено');}catch(e){const error=form.querySelector('.form-error');if(error)error.textContent=e.message;else toast(e.message,true);}finally{if(button.isConnected)button.disabled=false;}});
 return {names,click,nav:user=>[['staff-home','grid'],['staff-projects','folder'],['staff-tasks','list'],['staff-requests','file'],...(user.role==='admin'?[['admin-users','building'],['admin-moderation','shield']]:[]),['staff-audit','clock']],content:route=>{if(!s()||!isStaff(s().user))return null;if(route.page==='staff-home')return home();if(route.page==='staff-projects')return projects();if(route.page==='staff-tasks')return tasks();if(route.page==='staff-requests')return requests();if(route.page==='admin-users')return admin()?users():empty('Нет доступа');if(route.page==='admin-moderation')return admin()?moderation():empty('Нет доступа');if(route.page==='staff-audit')return heading('Журнал сотрудников','Действия команды сохраняются с автором и временем.')+auditPanel();if(route.page==='estimate')return readEstimate(route);return null;}};
}


